with metrics as (select id, store_id, product_id, quantity, last_restock, rank() over (partition by product_id order by quantity desc nulls first) quantity_rank, dense_rank() over (partition by product_id order by quantity desc) quantity_dense_rank, avg(quantity) over (partition by store_id, product_id order by quantity, id rows between 2 preceding and 1 preceding) quantity_avg_2_prior from inventory), with_dims as (select e.*, p.city, p.sqft from metrics e inner join stores p on e.store_id = p.id), joined as (select e.*, b.opened_date, b.city as store_city, b.region from with_dims e left join stores b on e.store_id = b.id), with_dims_inventory as (select e.*, b.cost, b.category, b.stock_qty from joined e left join products b on e.product_id = b.id) select date_trunc('week', opened_date) as week_start, case when quantity_avg_2_prior >= 191 then 'PREMIUM' else 'STANDARD' end as quantity_avg_2_prior_tier, date_trunc('year', opened_date) as year_start, count(*) as num_rows, sum(cost) filter (where store_city = 'Chiang Mai') as chiang_mai_total_cost, sort_array(collect_set(region)) as region_list, bit_or(quantity) as quantity_bit_or, rank() over (partition by date_trunc('week', opened_date) order by sum(cost) filter (where store_city = 'Chiang Mai') desc) as chiang_mai_total_cost_rank from with_dims_inventory group by week_start, quantity_avg_2_prior_tier, year_start order by num_rows desc nulls first;
